const items = $input.all();
const output = [];

const DAY_MS = 24 * 60 * 60 * 1000;


// 한국 날짜 기준 오늘 YYYY-MM-DD
function getTodayKST() {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Seoul',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date());

  const year = parts.find(p => p.type === 'year').value;
  const month = parts.find(p => p.type === 'month').value;
  const day = parts.find(p => p.type === 'day').value;

  return `${year}-${month}-${day}`;
}


function parseDate(dateString) {
  return new Date(`${dateString}T00:00:00Z`);
}


function formatDate(date) {
  return date.toISOString().slice(0, 10);
}


function addDays(date, days) {
  return new Date(date.getTime() + (days * DAY_MS));
}


const todayString = getTodayKST();
const today = parseDate(todayString);


for (const item of items) {
  const {
    customer_id,
    customer_name,
    contract_end_date,
    schedule_type,
    privacy_consent,
    recontact_consent,
  } = item.json;


  // 약정 종료일 없음
  if (!contract_end_date) {
    output.push({
      json: {
        success: true,
        feature_id: 'F-06',
        status: 'not_scheduled',
        reason: 'contract_end_date_missing',
        customer_id: customer_id ?? null,
        schedule_type: 'contract'
      }
    });

    continue;
  }


  const contractEnd = parseDate(contract_end_date);


  // 약정 종료일 형식 오류
  if (Number.isNaN(contractEnd.getTime())) {
    output.push({
      json: {
        success: true,
        feature_id: 'F-06',
        status: 'not_scheduled',
        reason: 'invalid_contract_end_date',
        customer_id: customer_id ?? null,
        schedule_type: 'contract',
        contract_end_date
      }
    });

    continue;
  }


  const remainingDays = Math.round(
    (contractEnd.getTime() - today.getTime()) / DAY_MS
  );


  // 이미 약정 만료
  if (remainingDays <= 0) {
    output.push({
      json: {
        success: true,
        feature_id: 'F-06',
        status: 'not_scheduled',
        reason: 'contract_expired',
        customer_id,
        schedule_type: 'contract',
        contract_end_date
      }
    });

    continue;
  }


  const schedules = [];


  // 1. 90일 이상
  if (remainingDays >= 90) {
    schedules.push({
      schedule_subtype: 'contract_notice_1',
      scheduledDate: addDays(
        today,
        Math.ceil(remainingDays / 3)
      ),
      contact_reason: '약정 만료 예정 1차 안내',
    });

    schedules.push({
      schedule_subtype: 'contract_notice_2',
      scheduledDate: addDays(
        today,
        Math.ceil((remainingDays * 2) / 3)
      ),
      contact_reason: '약정 만료 예정 2차 안내',
    });
  }


  // 2. 30 ~ 89일
  else if (remainingDays >= 30) {
    schedules.push({
      schedule_subtype: 'contract_notice_1',
      scheduledDate: addDays(
        today,
        Math.ceil(remainingDays / 3)
      ),
      contact_reason: '약정 만료 예정 1차 안내',
    });

    schedules.push({
      schedule_subtype: 'contract_notice_2',
      scheduledDate: addDays(contractEnd, -7),
      contact_reason: '약정 만료 7일 전 안내',
    });
  }


  // 3. 15 ~ 29일
  else if (remainingDays >= 15) {
    schedules.push({
      schedule_subtype: 'contract_notice_1',
      scheduledDate: addDays(
        today,
        Math.ceil(remainingDays / 3)
      ),
      contact_reason: '약정 만료 예정 1차 안내',
    });

    schedules.push({
      schedule_subtype: 'contract_notice_2',
      scheduledDate: addDays(contractEnd, -3),
      contact_reason: '약정 만료 3일 전 안내',
    });
  }


  // 4. 8 ~ 14일
  else if (remainingDays >= 8) {
    schedules.push({
      schedule_subtype: 'contract_notice_1',
      scheduledDate: addDays(contractEnd, -3),
      contact_reason: '약정 만료 3일 전 안내',
    });
  }


  // 5. 1 ~ 7일
  else {
    const urgentOffset = remainingDays >= 2 ? 1 : 0;

    schedules.push({
      schedule_subtype: 'contract_notice_1',
      scheduledDate: addDays(today, urgentOffset),
      contact_reason: '약정 만료 임박 안내',
    });
  }


  for (const schedule of schedules) {
    output.push({
      json: {
        customer_id,
        customer_name,

        schedule_type:
          schedule_type ?? 'contract',

        contract_end_date,

        privacy_consent,
        recontact_consent,

        reference_date:
          contract_end_date,

        schedule_subtype:
          schedule.schedule_subtype,

        scheduled_contact_date:
          formatDate(schedule.scheduledDate),

        contact_reason:
          schedule.contact_reason,

        remaining_contract_days:
          remainingDays,

        expected_notice_count:
          schedules.length
      }
    });
  }
}


return output;

const input = $input.first().json;

return [
  {
    json: {
      success: true,
      feature_id: 'F-06',
      status: 'no_cleanup_required',
      customer_id: input.customer_id ?? null,
      schedule_type: 'contract',
      message: '정리할 기존 약정 2차 안내 일정이 없습니다.'
    }
  }
];

const saved = $('약정 스케줄 저장').item.json;

return [
  {
    json: {
      success: true,
      feature_id: 'F-06',
      status: 'scheduled',

      schedule_id: saved.schedule_id ?? null,
      customer_id: saved.customer_id ?? null,

      schedule_type: saved.schedule_type ?? 'contract',
      schedule_subtype: saved.schedule_subtype ?? null,

      scheduled_contact_at:
        saved.scheduled_contact_at ?? null,

      contact_reason:
        saved.contact_reason ?? null
    }
  }
];

const saved = $input.first().json;

return [
  {
    json: {
      success: true,
      feature_id: 'F-06',
      status: 'cancelled',
      reason: 'contract_second_notice_no_longer_required',

      schedule_id: saved.schedule_id ?? null,
      customer_id: saved.customer_id ?? null,

      schedule_type: saved.schedule_type ?? 'contract',
      schedule_subtype:
        saved.schedule_subtype ?? 'contract_notice_2'
    }
  }
];
